import { expect, type Page } from "@playwright/test";
import { pathToFileURL } from "node:url";
import { resolve } from "node:path";
import { createGame } from "../src/game/transition.ts";
import { generateDeck } from "../src/game/deck.ts";
import { isGridSize } from "../src/game/boardCode.ts";
import { SELECTION_KIND } from "../src/game/constants.ts";
import { encodeSnapshot } from "../src/game/snapshot.ts";

export const REPLAYABLE_CODE = "np1-4-1";

export function cardButtons(page: Page) {
  return page.locator(".board-grid > button.card");
}

export function deckFor(boardCode: string): readonly number[] {
  const parts = boardCode.split("-");
  const size = Number(parts[1]);
  const seed = Number(parts[2]);
  if (!isGridSize(size) || !Number.isSafeInteger(seed)) throw new Error("Invalid test board code");
  return generateDeck(size, seed);
}

export function pairsFor(deck: readonly number[]): readonly (readonly [number, number])[] {
  const positions = new Map<number, number[]>();
  deck.forEach((face, index) => {
    const existing = positions.get(face) ?? [];
    existing.push(index);
    positions.set(face, existing);
  });
  const pairs: Array<readonly [number, number]> = [];
  for (const indexes of positions.values()) {
    const first = indexes[0];
    const second = indexes[1];
    if (first === undefined || second === undefined) throw new Error("Test deck has incomplete pairs");
    pairs.push([first, second]);
  }
  return pairs;
}

export function mismatchFor(deck: readonly number[]): readonly [number, number] {
  for (let first = 0; first < deck.length; first += 1) {
    for (let second = first + 1; second < deck.length; second += 1) {
      if (deck[first] !== deck[second]) return [first, second];
    }
  }
  throw new Error("Test deck has no distinct faces");
}

export function completedSnapshot(boardCode: string, elapsedMs = 1200): string {
  const game = createGame(boardCode);
  if (!game) throw new Error("Invalid completed snapshot board");
  const matched = Array.from({ length: game.deck.length }, (_, index) => index);
  return encodeSnapshot({
    ...game,
    matched,
    selection: { kind: SELECTION_KIND.closed },
    moves: game.deck.length / 2,
    elapsedMs,
    started: true,
  });
}

export async function loadBoard(page: Page, boardCode: string): Promise<void> {
  await page.getByText("Reproduce a game", { exact: true }).click();
  await page.getByLabel("Board code").fill(boardCode);
  await page.getByRole("button", { name: "Load board" }).click();
  await expect(cardButtons(page)).toHaveCount(Number(boardCode.split("-")[1]) ** 2);
}

export async function loadSnapshot(page: Page, text: string): Promise<void> {
  await page.getByText("Reproduce a game", { exact: true }).click();
  await page.getByLabel("Snapshot JSON").fill(text);
  await page.getByRole("button", { name: "Load snapshot" }).click();
}

export function offlineHtmlUrl(): string {
  return pathToFileURL(resolve("dist/index.html")).href;
}

export async function revealPairs(page: Page, pairs: readonly (readonly [number, number])[]): Promise<void> {
  const cards = cardButtons(page);
  for (const [first, second] of pairs) {
    await cards.nth(first).click();
    await cards.nth(second).click();
  }
}

import { expect, test } from "@playwright/test";
import { cardButtons, deckFor, loadBoard, mismatchFor, offlineHtmlUrl, REPLAYABLE_CODE } from "./support.ts";

test("the file distribution plays without network access and starts with hidden cards", async ({ page }) => {
  const outsideRequests: string[] = [];
  page.on("request", (request) => {
    if (!request.url().startsWith("file:")) outsideRequests.push(request.url());
  });
  await page.goto(offlineHtmlUrl());
  await expect(page.getByRole("heading", { name: "Neon Pairs" })).toBeVisible();
  await expect(cardButtons(page)).toHaveCount(16);
  await expect(page.getByText("Moves: 0")).toBeVisible();
  await expect(page.getByText("Pairs: 0/8")).toBeVisible();
  await expect(page.getByText("Time: 0:00")).toBeVisible();
  await expect(page.locator("svg.face-artwork")).toHaveCount(0);
  await expect(page.locator("body")).not.toContainText("cyan solid circle");
  await expect(page.locator("details")).not.toHaveAttribute("open", "");
  expect(await page.evaluate(() => document.activeElement?.tagName ?? null)).not.toBe("BUTTON");
  expect(outsideRequests).toEqual([]);
});

test("repeats, matches, misses, and keeps non-card interactions out of turns", async ({ page }) => {
  await page.goto(offlineHtmlUrl());
  await loadBoard(page, REPLAYABLE_CODE);
  const cards = cardButtons(page);
  await cards.nth(0).click();
  await cards.nth(0).click();
  await expect(page.getByText("Moves: 0")).toBeVisible();
  const deck = deckFor(REPLAYABLE_CODE);
  const pair = deck.findIndex((face, index) => index > 0 && deck[0] === face);
  expect(pair).toBeGreaterThan(0);
  await cards.nth(pair).click();
  await expect(page.getByText("Moves: 1")).toBeVisible();
  await expect(page.getByText("Pairs: 1/8")).toBeVisible();

  const [first, second] = mismatchFor(deck);
  await cards.nth(first).click();
  await cards.nth(second).click();
  await expect(page.getByText("Moves: 2")).toBeVisible();
  await expect(page.getByRole("status")).toHaveText("No match. Cards close after a short pause.");
  await cards.nth(4).click();
  await cards.nth(5).click({ button: "right" });
  await cards.nth(6).dispatchEvent("pointercancel");
  await expect(page.getByText("Moves: 2")).toBeVisible();
  await page.waitForTimeout(850);
  await expect(cards.nth(first)).toHaveAttribute("aria-label", /closed$/);
  await expect(cards.nth(second)).toHaveAttribute("aria-label", /closed$/);
});

test("uses one roving tab stop with bounded, modifier-free arrow navigation", async ({ page }) => {
  await page.goto(offlineHtmlUrl());
  await page.getByLabel("Grid size").focus();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "New Game" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "Restart" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(cardButtons(page).nth(0)).toBeFocused();
  await page.keyboard.press("ArrowLeft");
  await expect(cardButtons(page).nth(0)).toBeFocused();
  await page.keyboard.press("ArrowRight");
  await expect(cardButtons(page).nth(1)).toBeFocused();
  await page.keyboard.press("Control+ArrowRight");
  await expect(cardButtons(page).nth(1)).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByText("Reproduce a game", { exact: true })).toBeFocused();
  expect(await cardButtons(page).evaluateAll((buttons) => buttons.filter((button) => button.tabIndex === 0).length)).toBe(1);
});

